-- ==========================================================
-- seckill-service 最终版测试数据（与 seckill.sql 完全对齐）
-- ==========================================================
-- 设计原则：
--   1. 主链路稳定：id 与 user_id 一一对应，避免随机错误
--   2. 压测可重复：使用确定性数据生成逻辑
--   3. 样例数据完备：包含订单/支付/死信表样例，方便直查
-- ==========================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 固定基准时间，避免 NOW() 导致每次导入结果不同
SET @seed_now = TIMESTAMP('2026-05-08 10:00:00');

-- ==========================================================
-- 1) User DB
-- ==========================================================
USE `seckill_user`;

TRUNCATE TABLE `user_address`;
TRUNCATE TABLE `user`;

-- 1.1 用户表：1000个测试用户
-- 说明：这里改为显式 VALUES，不使用 CTE / WITH RECURSIVE / seq / n，避免 SQL 编辑器解析报错。





-- 1.2 收货地址表：稳定映射（id = user_id，前1000条）
-- 说明：显式 VALUES，保证导入确定性，并避免 IDE 无法解析 seq/n。





-- 已删除第二批随机地址：
--   1. 保证 user_id = address_id 的主链路稳定
--   2. 保证每次导入数据完全一致
--   3. 避免压测时因随机地址归属导致问题难以复现

