-- 4.2 死信消息样例（测试 DLQ 查询和重放）
-- raw_payload 使用完整 snake_case 业务消息，便于 ReplayDeadLetter 直接反序列化重放。
-- order_no/request_id 使用空字符串而不是 NULL，兼容 NOT NULL DEFAULT '' 的表结构。
    `event_id`, `topic`, `partition_id`, `offset_id`, `order_no`, `request_id`,
    `trace_id`, `retry_count`, `error_message`, `raw_payload`, `status`
) VALUES
      ('evt_20260508_001', 'seckill.order', 0, 12345, 'ORD202605080002', 'REQ_002_def456',
       'trace_20260508_0001', 3, '库存扣减失败：商品库存不足',
       '{"order_no":"ORD202605080002","request_id":"REQ_002_def456","user_id":2,"sku_id":1001,"activity_id":1,"product_id":1,"product_name":"iPhone 15 Pro 256G","product_image":"https://example.com/images/iphone15pro.jpg","quantity":1,"address_id":2,"coupon_id":0,"order_amount":19900,"coupon_discount":0,"final_amount":19900,"seckill_price":19900,"version":1,"timestamp":1778220000,"event_id":"evt_20260508_001","trace_id":"trace_20260508_0001","retry_count":3}',
       'FAILED'),

      ('evt_20260508_002', 'seckill.order.retry', 1, 67890, '', '',
       'trace_20260508_0002', 5, '支付超时：超过30分钟未支付',
       '{"order_no":"ORD202605070003","request_id":"REQ_003_ghi789","user_id":3,"sku_id":2001,"activity_id":2,"product_id":2,"product_name":"MacBook Pro 14英寸","product_image":"https://example.com/images/macbook.jpg","quantity":1,"address_id":3,"coupon_id":0,"order_amount":899900,"coupon_discount":0,"final_amount":899900,"seckill_price":899900,"version":1,"timestamp":1778216400,"event_id":"evt_20260508_002","trace_id":"trace_20260508_0002","retry_count":5}',
       'PENDING'),

      ('evt_20260508_003', 'seckill.order.dlq', 2, 98765, 'ORD202605080005', 'REQ_005_mno345',
       'trace_20260508_0003', 6, '消息反序列化失败：字段缺失或格式错误',
       '{"order_no":"ORD202605080005","request_id":"REQ_005_mno345","user_id":5,"sku_id":6001,"activity_id":1,"product_id":7,"product_name":"库存1件商品","product_image":"https://example.com/images/last_one.jpg","quantity":1,"address_id":5,"coupon_id":0,"order_amount":9900,"coupon_discount":0,"final_amount":9900,"seckill_price":9900,"version":1,"timestamp":1778223600,"event_id":"evt_20260508_003","trace_id":"trace_20260508_0003","retry_count":6}',
       'FAILED');

-- 4.3 本地消息表样例（测试 Outbox 模式）
