) VALUES
      ('outbox_20260508_001', 'Order', 'ORD202605080002', 'seckill.order.paid',
       '{"eventType":"OrderPaidEvent","orderNo":"ORD202605080002","userId":2,"amount":19900}', 0, 0, @seed_now),

      ('outbox_20260508_002', 'Order', 'ORD202605080003', 'seckill.order',
       '{"eventType":"OrderCreatedEvent","orderNo":"ORD202605080003","userId":5,"skuId":1001}', 1, 1, NULL);

