SELECT '=== 测试数据汇总 ===' AS '';
SELECT '-- User DB --' AS '';
SELECT CONCAT('用户数: ', COUNT(*)) AS '统计' FROM seckill_user.user;
SELECT CONCAT('地址数: ', COUNT(*), ' (稳定映射1000条，user_id = address_id)') AS '统计' FROM seckill_user.user_address;
SELECT '' AS '';
SELECT '-- Product DB --' AS '';
SELECT CONCAT('商品数: ', COUNT(*)) AS '统计' FROM seckill_product.product;
SELECT CONCAT('分类数: ', COUNT(*)) AS '统计' FROM seckill_product.category;
SELECT '' AS '';
SELECT '-- Core DB --' AS '';
SELECT CONCAT('活动数: ', COUNT(*)) AS '统计' FROM seckill_core.seckill_activity;
SELECT CONCAT('SKU数: ', COUNT(*)) AS '统计' FROM seckill_core.seckill_sku;
SELECT CONCAT('优惠券数: ', COUNT(*)) AS '统计' FROM seckill_core.coupon;
SELECT CONCAT('订单数: ', COUNT(*)) AS '统计' FROM seckill_core.seckill_order;
SELECT CONCAT('订单收货快照数: ', COUNT(*)) AS '统计' FROM seckill_core.order_shipping;
SELECT '' AS '';
SELECT '-- Pay DB --' AS '';
SELECT CONCAT('支付信息数: ', COUNT(*)) AS '统计' FROM seckill_pay.pay_info;
SELECT CONCAT('死信消息数: ', COUNT(*)) AS '统计' FROM seckill_pay.mq_dead_letter_message;
SELECT CONCAT('本地消息数: ', COUNT(*)) AS '统计' FROM seckill_pay.message_outbox;

SET FOREIGN_KEY_CHECKS = 1;